catalog_script_client.script:
function onLoad() {
    var today = new Date();
    today.setHours(0, 0, 0, 0);

    var yyyy = today.getFullYear();
    var mm = ('0' + (today.getMonth() + 1)).slice(-2);
    var dd = ('0' + today.getDate()).slice(-2);
    var todayDate = yyyy + '-' + mm + '-' + dd;

    // Set today's date as default
    if (!g_form.getValue('start_date')) {
        g_form.setValue('start_date', todayDate);
    }

    // Set minimum date, if supported by this form
    if (typeof g_form.setDateRange === 'function') {
        g_form.setDateRange('start_date', todayDate, '');
    }

	// Populate with the logged-in user's name
        g_form.setValue('requested_by', g_user.userID);
    // if (!g_form.getValue('requested_for')) {
    // }
}
